SELECT MAX(COUNT(DISTINCT p.procedure_id)) AS max_procedures FROM physionet-data.mimiciv_3_1_hosp.procedures_icd p JOIN physionet-data.mimiciv_3_1_hosp.patients pt ON p.subject_id = pt.subject_id WHERE pt.gender = 'M' AND pt.age >= 85 AND EXTRACT(YEAR FROM p.chartdate) BETWEEN 2015 AND 2020 AND p.icd_code IN ('I60.0', 'I60.1', 'I60.2', 'I60.3', 'I60.4', 'I60.5', 'I60.6', 'I60.7', 'I60.8', 'I60.9') GROUP BY p.subject_id HAVING COUNT(DISTINCT pt.hadm_id) > 1;